import { differenceInMonths, differenceInYears, isValid, parseISO } from 'date-fns';
import defaultAvatar from '@/assets/imgs/user.png';
import { cn } from '@/lib/utils';
import type { Insurance } from '@/types/insurance.types';

function display(v: unknown) {
    if (v == null || v === '') return '—';
    return String(v);
}

function subscriptionDuration(start?: string, end?: string): string {
    if (!start || !end) return '—';
    try {
        const s = parseISO(start);
        const e = parseISO(end);
        if (!isValid(s) || !isValid(e)) return '—';
        const y = differenceInYears(e, s);
        if (y >= 1) return `${y} ${y === 1 ? 'سنة' : 'سنوات'}`;
        const m = differenceInMonths(e, s);
        return m > 0 ? `${m} ${m === 1 ? 'شهر' : 'أشهر'}` : '—';
    } catch {
        return '—';
    }
}

function isSubscriptionActive(endDate?: string): boolean {
    if (!endDate) return false;
    try {
        const e = parseISO(endDate);
        if (!isValid(e)) return false;
        return e >= new Date(new Date().toDateString());
    } catch {
        return false;
    }
}

type InsurancePageHeroProps = {
    insurance: Insurance | null;
    loading: boolean;
};

export default function InsurancePageHero({ insurance, loading }: InsurancePageHeroProps) {
    if (loading) {
        return (
            <div className="w-full mt-6 rounded-2xl bg-primery-blue-800 min-h-[200px] animate-pulse" aria-hidden />
        );
    }

    const active = isSubscriptionActive(insurance?.end_date);

    return (
        <div className="w-full mt-6 p-6 md:p-8 bg-primery-blue-800 rounded-2xl text-white-blue-50 shadow-[0px_4px_24px_-4px_rgba(0,0,0,0.15)]">
            <div className="flex flex-col lg:flex-row gap-8 lg:gap-10 lg:items-center">
                <div className="flex justify-center lg:justify-start shrink-0">
                    <div className="w-[140px] h-[140px] md:w-[172px] md:h-[172px] rounded-full overflow-hidden border-4 border-white/25 bg-white/10">
                        <img src={defaultAvatar} alt="" className="w-full h-full object-cover" />
                    </div>
                </div>

                <div className="flex-1 min-w-0 grid grid-cols-1 md:grid-cols-2 gap-x-10 gap-y-4">
                    <div className="space-y-1">
                        <p className="text-sm text-white-blue-300 font-medium">الاسم</p>
                        <p className="text-lg md:text-xl font-bold leading-snug break-words">
                            {display(insurance?.employee?.name)}
                        </p>
                    </div>
                    <div className="space-y-1">
                        <p className="text-sm text-white-blue-300 font-medium">تاريخ بدء الاشتراك</p>
                        <p className="text-base md:text-lg font-semibold">{display(insurance?.start_date)}</p>
                    </div>

                    <div className="space-y-1">
                        <p className="text-sm text-white-blue-300 font-medium">رقم المشترك</p>
                        <p className="text-base md:text-lg font-semibold tabular-nums">{display(insurance?.id)}</p>
                    </div>
                    <div className="space-y-1">
                        <p className="text-sm text-white-blue-300 font-medium">تاريخ انتهاء الاشتراك</p>
                        <p className="text-base md:text-lg font-semibold">{display(insurance?.end_date)}</p>
                    </div>

                    <div className="space-y-1 md:col-span-2 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pt-2 border-t border-white/10">
                        <div>
                            <p className="text-sm text-white-blue-300 font-medium mb-1">حالة الاشتراك</p>
                            <span
                                className={cn(
                                    'inline-flex items-center px-2.5 py-1 rounded-md text-sm font-semibold',
                                    active
                                        ? 'bg-[#DAF8E6] text-[#1A8245]'
                                        : 'bg-[#FEEBEB] text-[#E10E0E]',
                                )}
                            >
                                {insurance?.end_date ? (active ? 'نشط' : 'منتهي') : '—'}
                            </span>
                        </div>
                        <div className="text-start sm:text-end">
                            <p className="text-sm text-white-blue-300 font-medium mb-1">مدة الاشتراك</p>
                            <p className="text-base md:text-lg font-semibold">
                                {subscriptionDuration(insurance?.start_date, insurance?.end_date)}
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
