import { useMemo } from 'react';
import EmployeeInsuranceDataSection from './EmployeeInsuranceDataSection';
import InsuranceSummaryCards from './InsuranceSummaryCards';
import InsuranceList from '../insuranceList/InsuranceList';
import type { Insurance } from '@/types/insurance.types';

type InsuranceInfoTabProps = {
    insurance: Insurance | null;
    insuranceLoading: boolean;
};

export default function InsuranceInfoTab({ insurance, insuranceLoading }: InsuranceInfoTabProps) {
    const relatives = insurance?.relatives;

    const summary = useMemo(() => {
        const amount = insurance?.amount;
        const parsed = typeof amount === 'number' ? amount : Number(amount);
        const insuranceValue = Number.isFinite(parsed) && parsed > 0 ? parsed : 10_000;

        let beneficiariesCount = 0;
        if (insurance) {
            beneficiariesCount = Array.isArray(relatives) ? relatives.length : 0;
        }

        return { insuranceValue, beneficiariesCount };
    }, [insurance, relatives]);

    const insuranceIdStr = insurance?.id != null ? String(insurance.id) : undefined;

    return (
        <div className="w-full mt-6">
            <InsuranceSummaryCards
                insuranceValue={summary.insuranceValue}
                beneficiariesCount={summary.beneficiariesCount}
            />

            {!insuranceLoading && <EmployeeInsuranceDataSection employeeInsuranceData={insurance} />}
            <InsuranceList insuranceId={insuranceIdStr} />
        </div>
    );
}
