import { ColumnDef, Row } from '@tanstack/react-table';
import { InsuranceRelatives } from '@/types/insurance.types';
import TrashIcon from '@/components/icons/TrashIcon';
import EditIcon from '@/components/icons/EditIcon';

export type InsuranceBeneficiaryColumnHandlers = {
    onEditBeneficiary: (row: InsuranceRelatives) => void;
};

function displayDate(v: string | null | undefined) {
    if (v == null || v === '') return '—';
    return v;
}

function createActionsCell(onEditBeneficiary: (row: InsuranceRelatives) => void) {
    return function ActionsCell({ row }: { row: Row<InsuranceRelatives> }) {
        return (
            <div className="me-6 text-end">
                <button
                    type="button"
                    onClick={() => onEditBeneficiary(row.original)}
                    className="text-primary hover:text-primary/80"
                >
                    <EditIcon className="text-primery-blue-400" />
                </button>
                <button type="button" className="hover:bg-white-blue-300 rounded-full p-1" aria-label="حذف">
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>
        );
    };
}

export function createInsuranceBeneficiaryColumns({
    onEditBeneficiary,
}: InsuranceBeneficiaryColumnHandlers): ColumnDef<InsuranceRelatives>[] {
    const ActionsCell = createActionsCell(onEditBeneficiary);

    return [
        {
            accessorKey: 'id',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        رقم المشترك
                    </div>
                );
            },
            cell: ({ row }) => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    {row.original.id}
                </div>
            ),
        },
        {
            accessorKey: 'name',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        اسم المشترك
                    </div>
                );
            },
            cell: ({ row }) => (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    {row.original.name}
                </div>
            ),
        },
        {
            accessorKey: 'relationship',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        صلة القرابة
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                        {row.original.relationship ?? '—'}
                    </div>
                );
            },
        },
        {
            accessorKey: 'start_date',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        تاريخ بدء الاشتراك
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                        {displayDate(row.original.start_date)}
                    </div>
                );
            },
        },
        {
            accessorKey: 'end_date',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        تاريخ انتهاء الاشتراك
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                        {displayDate(row.original.end_date)}
                    </div>
                );
            },
        },
        {
            accessorKey: 'amount',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        قيمة الاشتراك
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                        {row.original.amount != null && row.original.amount !== '' ? `${row.original.amount} ر.س` : '—'}
                    </div>
                );
            },
        },
        {
            accessorKey: 'status',
            header: () => {
                return (
                    <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        الحالة
                    </div>
                );
            },
            cell: ({ row }) => {
                return (
                    <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                        {row.original.status ?? '—'}
                    </div>
                );
            },
        },
        {
            id: 'actions',
            header: () => {
                return (
                    <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                        مشاهدة
                    </div>
                );
            },
            cell: ({ row }) => <ActionsCell row={row} />,
        },
    ];
}
