import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { useNavigate } from 'react-router-dom';
import { Department } from '@/types/department.types';

interface Props {
    department?: Department | null;
    isEdit?: boolean;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
    onCloseDialog?: () => void;
}
export default function Submission({
    department,
    isEdit = false,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
    onCloseDialog,
}: Props) {
    const isEditFlow = Boolean(department) || isEdit;
    const navigate = useNavigate();

    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row justify-end items-center mt-8">
                {isEditFlow ? (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        {department ? 'إلغاء إضافة المستفيد' : 'إلغاء التعديل'}
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:px-[87px] bg-red-error-50 text-[#A21515] hover:bg-red-error-600 hover:text-white-blue-50 xl:py-3 border bordr-[#E8EFF6] xl:font-semibold"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {isEditFlow ? (
                        <PrimaryButton
                            type="submit"
                            className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6"
                            disabled={loading}
                        >
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton
                            type="submit"
                            className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6"
                            disabled={loading}
                        >
                            {loading ? 'جاري التحميل...' : 'اضافة'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onOpenChange={setShowCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    setShowCancelPopup(false);
                    onCloseDialog?.();
                    navigate('/insurance');
                }}
                text1={isEditFlow ? 'إلغاء تعديل بيانات المستفيد' : 'إلغاء إضافة مستفيد'}
                text2={
                    isEditFlow
                        ? 'أنت على وشك إلغاء عملية تعديل بيانات المستفيد دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة مستفيد جديد دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1={isEditFlow ? 'إكمال التعديل' : 'إكمال الإضافة'}
                textButton2={isEditFlow ? 'إلغاء التعديل' : 'إلغاء الإضافة'}
            />
            <SuccessPopup
                text1={isEditFlow ? 'تم تعديل بيانات المستفيد بنحاح' : 'تم إضافة مستفيد جديد بنحاح'}
                text2={isEditFlow ? 'تم تعديل بيانات المستفيد بنحاح' : 'تم تسجيل بيانات المستفيد الجديد بنجاح.'}
                textButton1="العودة لقائمة المستفيدين"
                textButton2={isEditFlow ? 'تعديل بيانات اخرى' : 'إضافة مستفيد أخر'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    navigate('/insurance');
                    setShowSuccessPopup(false);
                }}
            />
        </>
    );
}
