import { useEffect, useState } from 'react';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import InsurancePageHero from '../components/InsurancePageHero';
import SelectabelContent from '../components/SelectabelContent';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import type { Insurance } from '@/types/insurance.types';

const InsurancePage = () => {
    const [insurance, setInsurance] = useState<Insurance | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.insurance.employeeMe });
                if (!cancelled) setInsurance(res.data?.data ?? null);
            } catch {
                if (!cancelled) setInsurance(null);
            } finally {
                if (!cancelled) setLoading(false);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    return (
        <div className="w-full mt-6 mb-24 px-1 sm:px-0">
            <UnderlineHeading text="التأمينات" />
            <InsurancePageHero insurance={insurance} loading={loading} />
            <SelectabelContent insurance={insurance} insuranceLoading={loading} />
        </div>
    );
};

export default InsurancePage;
