import { useCallback, useState } from 'react';
import { DataTableToolbar } from './data-table-toolbar';
import { columns } from './columns';
import { DataTable } from '@/components/tables/customTable/data-table';
import type { Insurance } from '@/types/insurance.types';
import type { FetchDataOptions } from '@/types/table.types';

export default function InsuranceCertificateRequestList({
    employeeInsuranceData,
}: {
    employeeInsuranceData: Insurance | null;
}) {
    const [data, setData] = useState<Insurance[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            setIsLoading(true);
            try {
                const rows = employeeInsuranceData ? [employeeInsuranceData] : [];
                const size = options.pageSize || 10;
                const page = options.pageIndex + 1;
                const start = (page - 1) * size;
                const pageSlice = rows.slice(start, start + size);
                setData(pageSlice);
                setPageCount(Math.max(1, Math.ceil(rows.length / size)));
                setTotalCount(rows.length);
            } catch (error) {
                console.error('Error fetching data:', error);
                setData([]);
            } finally {
                setIsLoading(false);
            }
        },
        [employeeInsuranceData],
    );

    return (
        <div className="mt-6 mb-20 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
