import InsuranceCertificateRequestList from './insuranceCertificateRequestList/InsuranceCertificateRequestList';
import InsuranceRequestsStatistics from './insuranceCertificateRequestList/InsuranceRequestsStatistics';
import type { Insurance } from '@/types/insurance.types';

type InsuranceCertificateRequestProps = {
    insurance: Insurance | null;
};

export default function InsuranceCertificateRequest({ insurance }: InsuranceCertificateRequestProps) {
    return (
        <div className="w-full mt-6">
            <InsuranceRequestsStatistics />
            <InsuranceCertificateRequestList employeeInsuranceData={insurance} />
        </div>
    );
}
